<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$uid=(int)currentUser()['id_user'];if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$lid=(int)$_POST['id_laporan'];$s=$koneksi->prepare('INSERT IGNORE INTO bookmark(id_user,id_laporan) VALUES(?,?)');$s->bind_param('ii',$uid,$lid);$s->execute();flash('Barang ditambahkan ke bookmark.');redirect('siswa/barang.php');}$pageTitle='Barang Ditemukan';$term=trim($_GET['q']??'');$sql="SELECT l.*,u.nama,k.nama_kategori,lo.nama_lokasi FROM laporan l JOIN users u ON u.id_user=l.id_user JOIN kategori k ON k.id_kategori=l.id_kategori JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi WHERE l.jenis_laporan='ditemukan' AND l.moderation_status='aktif' AND l.status<>'ditolak'";$st=null;if($term!==''){$sql.=' AND (l.nama_barang LIKE ? OR l.deskripsi LIKE ? OR lo.nama_lokasi LIKE ?)';$like='%'.$term.'%';$st=$koneksi->prepare($sql.' ORDER BY l.created_at DESC');$st->bind_param('sss',$like,$like,$like);$st->execute();$rows=$st->get_result();}else{$rows=$koneksi->query($sql.' ORDER BY l.created_at DESC');}require __DIR__.'/../includes/header.php';?><div class="panel"><div class="panel-head"><div><h2>Barang yang ditemukan</h2><small class="muted">Cari barang temuan yang mungkin merupakan milikmu.</small></div><span class="badge">Daftar publik</span></div><form class="searchbar"><input class="search" name="q" placeholder="Cari nama barang atau lokasi..." value="<?=e($term)?>"><button class="btn">Cari</button></form><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"><?php if(!$rows->num_rows):?><div class="empty">Belum ada barang yang cocok.</div><?php endif;while($r=$rows->fetch_assoc()):?><div class="panel" style="padding:13px;box-shadow:none"><div class="item-thumb" style="width:100%;height:130px;border-radius:14px;margin-bottom:12px"><?php if($r['foto_barang']):?><img src="<?=e(url('uploads/barang/'.$r['foto_barang']))?>" alt="Foto barang"><?php else:?><?php endif;?></div><span class="badge diproses">Ditemukan</span><h2 style="margin:10px 0 6px"><?=e($r['nama_barang'])?></h2><p class="muted" style="font-size:11px;line-height:1.6"><?=e($r['nama_kategori'])?> · <?=e($r['nama_lokasi'])?><br><?=e($r['deskripsi']??'Tidak ada deskripsi')?></p><div class="actions"><a class="btn" style="flex:1" href="klaim.php?id=<?=$r['id_laporan']?>">Ini barang saya</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id_laporan" value="<?=$r['id_laporan']?>"><button class="btn secondary" title="Simpan bookmark"></button></form></div></div><?php endwhile;?></div></div><?php require __DIR__.'/../includes/footer.php';?>
